package com.rpb.reservation.workforce.payroll.governance;
import static com.rpb.reservation.workforce.payroll.governance.TemplatePublicationDtos.*;
import com.rpb.reservation.walkin.api.CurrentActor;
import com.rpb.reservation.workforce.application.*;
import com.rpb.reservation.workforce.payroll.PayrollConfigurationRepository;
import com.rpb.reservation.workforce.payroll.PayrollRules;
import com.rpb.reservation.workforce.domain.WorkforceException;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)
public class TemplatePublicationService {
 private final TemplatePublicationRepository repository;private final WorkforceAudit audit;private final TemplatePublicationScope scope;
 public TemplatePublicationService(WorkforceAccess access,TemplatePublicationRepository repository,PayrollConfigurationRepository configs,WorkforceAudit audit){this.repository=repository;this.audit=audit;this.scope=new TemplatePublicationScope(access,repository);}
 public List<Draft> drafts(CurrentActor actor,UUID store){scope.head(actor,store);return repository.drafts(actor.tenantId()).stream().filter(d->{try{scope.authorizeExisting(actor,d.companyIds(),d.storeIds());return true;}catch(WorkforceException e){return false;}}).toList();}
 public PublicationDirectory directory(CurrentActor actor,UUID store){scope.head(actor,store);var companies=repository.companyOptions(actor.tenantId()).stream().filter(c->{try{scope.validate(actor,List.of(c.id()),List.of());return true;}catch(WorkforceException e){return false;}}).toList();var ids=companies.stream().map(c->c.id()).toList();var shops=repository.stores(actor.tenantId()).stream().filter(s->s.active()&&ids.contains(s.companyId())&&actor.canAccessStore(s.id())).map(s->new com.rpb.reservation.workforce.application.WorkforceDtos.StoreOption(s.id(),s.name(),s.companyId())).toList();return new PublicationDirectory(companies,shops);}
 @Transactional public Draft save(CurrentActor actor,UUID store,UUID id,DraftWrite c){scope.head(actor,store);if(id==null||c==null||c.expectedVersion()==null||c.expectedVersion()<0||c.includeFutureStores()==null)throw WorkforceException.invalid();String name=c.name()==null?"":c.name().trim();if(name.isEmpty()||name.length()>100)throw WorkforceException.invalid();var rule=PayrollRules.normalize(c.rule());var companies=scope.ids(c.companyIds(),true);var shops=scope.ids(c.storeIds(),false);if(shops.isEmpty()&&!c.includeFutureStores())throw WorkforceException.invalid();scope.validate(actor,companies,shops);repository.lock("master:"+id);var old=repository.draft(actor.tenantId(),id).orElse(null);if(old!=null)scope.authorizeExisting(actor,old.companyIds(),old.storeIds());if(old!=null&&(old.version()==c.expectedVersion()+1||c.expectedVersion()==0)&&old.name().equals(name)&&old.rule().equals(rule)&&old.companyIds().equals(companies)&&old.storeIds().equals(shops)&&old.includeFutureStores()==c.includeFutureStores())return old;if((old==null?0:old.version())!=c.expectedVersion())throw WorkforceException.conflict();var next=new Draft(id,c.expectedVersion()+1,name,rule,companies,shops,c.includeFutureStores());repository.save(actor.tenantId(),next);audit.changed(actor,store,"pay-template-master.save",id,old,next);return next;}
 @Transactional public Release publish(CurrentActor actor,UUID store,UUID id,Publish c){scope.head(actor,store);if(c==null||c.commandId()==null||c.expectedDraftVersion()==null||c.expectedDraftVersion()<1)throw WorkforceException.invalid();repository.lock("command:"+c.commandId());repository.lock("master:"+id);var payload=Map.of("masterId",id,"expectedDraftVersion",c.expectedDraftVersion());var replay=repository.replay(actor.tenantId(),actor.actorId(),store,c.commandId(),"publish",payload,Release.class);if(replay.isPresent()){var r=replay.get();scope.validate(actor,r.companyIds(),r.storeIds());return r;}var d=repository.draft(actor.tenantId(),id).orElseThrow(WorkforceException::missing);if(d.version()!=c.expectedDraftVersion())throw WorkforceException.conflict();scope.validate(actor,d.companyIds(),d.storeIds());var published=repository.publishedDraft(actor.tenantId(),id,d.version());Release r;if(published.isPresent())r=published.get();else{var existing=repository.stores(actor.tenantId()).stream().map(TemplatePublicationRepository.Store::id).sorted().toList();r=new Release(id,repository.latestVersion(actor.tenantId(),id)+1,d.version(),d.name(),d.rule(),d.companyIds(),d.storeIds(),d.includeFutureStores(),existing,repository.now(),actor.actorId());repository.publish(actor.tenantId(),r);audit.changed(actor,store,"pay-template.publish",id,null,r);}repository.command(actor.tenantId(),actor.actorId(),store,c.commandId(),"publish",payload,r);return r;}
}
